/**
 * Real reference data only - the exercise catalog.
 *
 * METADATA - muscle group, primary/secondary muscles, equipment, level,
 * mechanic, category and step-by-step instructions, for the 137 featured lifts -
 * comes from yuhonas/free-exercise-db (https://github.com/yuhonas/free-exercise-db),
 * released into the public domain under the Unlicense.
 *
 * MEDIA - the `imageUrl` still for every lift and the `gifUrl` animation for the
 * featured subset - is (c) Gym visual - https://gymvisual.com/ - redistributed
 * under terms that require it to stay at or below 180x180 px and to carry that
 * credit. Everything is bundled and local: no hotlinks, no upscaling, and the
 * stills must not be re-encoded above 180x180.
 *
 * The catalog is deliberately incomplete, and an absent value always means
 * "not confidently known" - never a guess. In total 1,045 of the 1,324 lifts
 * carry a `muscle` group and 279 do not; 1,188 entries have no instructions
 * (all 1,187 non-featured lifts plus a single featured entry). Non-featured
 * lifts carry only name-derived `equipment`; `level`, `mechanic`, `category`,
 * `instructions` and `muscle` are all omitted rather than inferred when the
 * source does not state them, so an empty `instructions` array and a missing
 * `muscle` read the same way: "we do not know".
 *
 * Non-featured `muscle` is derived from the name by a strict, ordered rule set
 * (first match wins): strip the equipment/tool prefix, then test the movement
 * in this order - Legs (squat, lunge, leg press, leg extension, leg curl, calf,
 * glute, hamstring, hip thrust, step-up, and stiff-leg/Romanian/straight-leg
 * deadlift), Back (deadlift, row, pulldown, pull-up, chin, shrug, lat, back
 * extension, hyperextension, face pull, reverse fly), Chest (bench press,
 * chest, fly, push-up, dip, pullover, pec), Shoulders (overhead/military/
 * shoulder/Arnold press, lateral/front raise, rear delt, upright row, behind
 * neck), Arms (curl, pushdown, extension, kickback, tricep, bicep, forearm,
 * wrist, preacher, hammer, skull) and Core (crunch, plank, sit-up, leg raise,
 * oblique, twist, ab, rollout, roller, knee raise, elbow to knee, wood chop,
 * Russian). A name that matches none is left WITHOUT `muscle` on purpose -
 * better absent than wrong, never a torso catch-all.
 *
 * There is deliberately NO template/program/demo data here: a new user's
 * schedule starts empty (see `makeEmptySchedule` in '@/lib/gymmate/store').
 * Screens let the user build their own week from `LIBRARY`.
 */

import type { ImageSourcePropType } from 'react-native';

export type Muscle = 'Chest' | 'Back' | 'Legs' | 'Shoulders' | 'Arms' | 'Core';

export const MUSCLES: Muscle[] = ['Chest', 'Back', 'Legs', 'Shoulders', 'Arms', 'Core'];

export interface LibraryExercise {
  /** Dataset id, verbatim (stable across releases). */
  id: string;
  /** Display name, title-cased from the dataset name. */
  name: string;
  /**
   * Coarse group used for UI filtering. Only present when the name matches one
   * of the documented movement rules - a fact we know, never a guess. Like
   * `level`/`mechanic`/`category`, an absent value means "unknown".
   */
  muscle?: Muscle;
  /** Raw dataset muscle keys, e.g. ['chest']. Empty when unknown. */
  primaryMuscles: string[];
  /** Raw dataset muscle keys, assisting muscles. Empty when unknown. */
  secondaryMuscles: string[];
  /** Display label, e.g. 'Barbell'. */
  equipment: string;
  /** 'Beginner' | 'Intermediate' | 'Expert'. Only present when authoritative. */
  level?: string;
  /** 'Compound' | 'Isolation'. Only present when authoritative. */
  mechanic?: string;
  /** 'Strength' | 'Powerlifting' | 'Olympic Weightlifting' | ... Only when authoritative. */
  category?: string;
  /** Real step-by-step instructions. Empty when unknown. */
  instructions: string[];
  /** Legacy names (and the raw dataset spelling) so old schedules keep resolving. */
  aliases?: string[];
  /** True for the curated gym-lift subset, the only entries with a `gifUrl`. */
  featured?: boolean;
  /** Bundled 180x180 still. (c) Gym visual - https://gymvisual.com/ */
  imageUrl: ImageSourcePropType;
  /** Bundled animated WebP, featured lifts only. (c) Gym visual. */
  gifUrl?: ImageSourcePropType;
}

